def need_umbrella(weather_desc):
    '''天気から傘が必要か判定'''
    rain_keywords = ['雨', 'rain', '雷', 'thunder', 'drizzle']
    for keyword in rain_keywords:
        if keyword in weather_desc.lower():
            return True
    return False

def get_weather_emoji(weather_desc):
    '''天気に応じた絵文字を返す'''
    if '晴' in weather_desc or 'clear' in weather_desc.lower():
        return '☀️'
    elif '雨' in weather_desc or 'rain' in weather_desc.lower():
        return '🌧️'
    elif '曇' in weather_desc or 'cloud' in weather_desc.lower():
        return '☁️'
    elif '雪' in weather_desc or 'snow' in weather_desc.lower():
        return '❄️'
    else:
        return '🌤️'

# モックデータ
mock_weather_data = {
    'weather': [{'description': '晴れ'}],
    'main': {'temp': 25, 'humidity': 60},
    'name': 'Tokyo'
}

weather_desc = mock_weather_data['weather'][0]['description']
temp = mock_weather_data['main']['temp']
humidity = mock_weather_data['main']['humidity']
city = mock_weather_data['name']

emoji = get_weather_emoji(weather_desc)

print('=' * 30)
print(f'{emoji} {city}の天気情報')
print('=' * 30)
print(f'天気: {weather_desc}')
print(f'気温: {temp}°C')
print(f'湿度: {humidity}%')
print('=' * 30)

# 傘が必要か判定
if need_umbrella(weather_desc):
    print('☔ 傘を持って行きましょう!')
else:
    print('☀️ 傘は不要です!')
print('=' * 30)
